const translations={ko:{skip:'프로젝트 바로가기',tagline:'좋은 아이디어가\n좋은 일상을 만듭니다.',home:'홈',projects:'프로젝트',about:'소개',headline:'좋은 아이디어가\n좋은 일상을\n만듭니다.',intro:'건강, 음식, 추억, 신앙.\n일상을 조금 더 풍요롭게 만드는\n후추의 작은 프로젝트들입니다.',browse:'프로젝트 보기',visit:'프로젝트 열기',shelf:'책장 속 다른 이야기',footer:'작은 아이디어로, 조금 더 좋은 일상.',studio:'후추 스튜디오 ↗',previous:'이전 프로젝트',next:'다음 프로젝트',select:'프로젝트 선택'},en:{skip:'Skip to projects',tagline:'Good ideas make\neveryday life better.',home:'Home',projects:'Projects',about:'About',headline:'Good ideas.\nA better\neveryday.',intro:'Health, food, memories, and faith.\nA collection of little projects\nto enrich everyday life.',browse:'Explore projects',visit:'Open project',shelf:'More stories on the shelf',footer:'Little ideas. A better everyday.',studio:'Huchu Studio ↗',previous:'Previous project',next:'Next project',select:'Select project'},jp:{skip:'プロジェクトへ',tagline:'よいアイデアが\nよい日常をつくる。',home:'ホーム',projects:'プロジェクト',about:'紹介',headline:'よいアイデアが\nよい日常を\nつくる。',intro:'健康、料理、思い出、信仰。\n日常を少し豊かにする\n小さなプロジェクト集です。',browse:'プロジェクトを見る',visit:'サイトを開く',shelf:'本棚のほかの物語',footer:'小さなアイデアで、もっとよい毎日。',studio:'Huchu Studio ↗',previous:'前のプロジェクト',next:'次のプロジェクト',select:'プロジェクトを選択'}};
let selected=0,language='ko';try{const saved=localStorage.getItem('preferredLanguage');if(translations[saved])language=saved;}catch{}
const $=id=>document.getElementById(id),number=i=>String(i+1).padStart(2,'0');
function render(){const t=translations[language],p=projects[selected],copy=p[language];document.documentElement.lang=language==='jp'?'ja':language;document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t[el.dataset.i18n];el.style.whiteSpace='pre-line';});document.querySelectorAll('[data-language]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.language===language)));$('book-number').textContent=number(selected);$('page-count').innerHTML=number(selected)+' <i>/</i> '+String(projects.length).padStart(2,'0');$('book-title').innerHTML=p.title;$('book-subtitle').textContent=copy[1];$('book-description').textContent=copy[2];$('book-category').textContent=p.category;$('project-link').href=p.url;$('hero-image').src=p.image || `./assets/approved-${p.id}-v2.webp`;$('hero-image').alt=copy[4];$('art-caption').hidden=p.id!=='bible';$('art-caption-title').textContent=({ko:'말씀 속에서\n새로운 하루를\n만나보세요.',en:'A new day\nwith His word.',jp:'聖書と出会う\n新しい一日。'})[language];$('previous').setAttribute('aria-label',t.previous);$('next').setAttribute('aria-label',t.next);
$('book-index').replaceChildren(...projects.map((project,i)=>{const b=document.createElement('button');b.className='index-item';b.dataset.project=String(i);b.setAttribute('aria-pressed',String(i===selected));b.innerHTML=`<span>${number(i)}</span>`;b.append(project[language][0]);b.addEventListener('click',()=>select(i));return b;}));
$('shelf').replaceChildren(...projects.flatMap((project,i)=>{if(i===selected)return[];const b=document.createElement('a');b.href=project.url;b.className='mini-book';b.dataset.project=String(i);b.setAttribute('aria-label',`${project[language][0]} — ${t.visit}`);b.innerHTML=`<span class="mini-copy"><span class="mini-number">${number(i)} <small> / PROJECT</small></span><span class="mini-title">${project[language][0]}</span><span class="mini-category">${project.category.split(' · ')[0]}</span><span class="mini-desc">${project[language][3]}</span><span class="mini-arrow" aria-hidden="true">↗</span></span><img src="${project.image || `./assets/approved-${project.id}-v2-small.webp`}" alt="" width="360" height="540" loading="lazy">`;return[b];}));}
function select(i){const focused=document.activeElement;const indexFocus=focused?.closest('#book-index')?Number(focused.dataset.project):null;selected=(i+projects.length)%projects.length;render();if(indexFocus!==null)$('book-index').querySelector(`[data-project="${indexFocus}"]`).focus({preventScroll:true});}
$('previous').addEventListener('click',()=>select(selected-1));$('next').addEventListener('click',()=>select(selected+1));document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{language=b.dataset.language;try{localStorage.setItem('preferredLanguage',language)}catch{}render();}));render();
